[Form]
public class ISDAppIntgDMFExecutionHistoryImportListFormPart extends FormRun implements ISDAppIntgDMFExecutionHistoryImportFilterForm
{
    private DMFOperationType                                    executionOperation = DMFOperationType::Import;
    private ISDAppIntgDMFExecutionHistoryImportViewModel        viewModel;
    private ISDAppIntgDMFExecutionHistoryStatusFilterOptions    exeHistoryStatusFilter;
    boolean                                                     isCallerTargetError;
    boolean                                                     isCallerAllCompleted;

}

/// <summary>
/// Initialize form
/// </summary>
public void init()
{
    exeHistoryStatusFilter = this.args().parmEnum();

    super();

    viewModel = ISDAppIntgDMFExecutionHistoryImportViewModel::construct(this, this.args().caller());

    isCallerTargetError = exeHistoryStatusFilter == ISDAppIntgDMFExecutionHistoryStatusFilterOptions::TargetError;
    isCallerAllCompleted = exeHistoryStatusFilter == ISDAppIntgDMFExecutionHistoryStatusFilterOptions::Ended;

    ViewStagingButtonHeaderEntity.enabled(isCallerTargetError);
    ViewRelatedStagingErrorButtonHeaderEntity.enabled(isCallerTargetError);
    CopyDataToTarget.enabled(isCallerTargetError);

    ViewStagingButtonChildEntity.enabled(isCallerTargetError);
    ViewStagingRelatedErrorButtonChildEntity.enabled(isCallerTargetError);
}

/// <summary>
/// Parm method to get/set current operation type
/// </summary>
/// <param name = "_executionOperation">Operation type on data project</param>
/// <returns>Current operation type</returns>
public DMFOperationType parmExecutionOperation(DMFOperationType _executionOperation = executionOperation)
{
    executionOperation = _executionOperation;
    return executionOperation;
}

/// <summary>
/// Returns the data source for a DMF definition group execution.
