/// <summary>
/// Returns the <c>Args</c> class instance used to initialize the task form.
/// </summary>
/// <returns>The args object.</returns>
public Args getCallingArgs()
{
    return this.args();
}

/// <summary>
/// Set form menu item button editable
/// </summary>
public void allowButtonEditable()
{
    boolean isCompositeEntity;

    if (isCallerTargetError)
    {
        isCompositeEntity = (DMFEntity::find(DMFDefinitionGroupExecution.Entity).EntityType == DMFEntityTypes::CompositEntity);

        ViewStagingButtonHeaderEntity.enabled(!isCompositeEntity);
        ViewRelatedStagingErrorButtonHeaderEntity.enabled(!isCompositeEntity);

        ViewStagingButtonChildEntity.enabled(isCompositeEntity);
        ViewStagingRelatedErrorButtonChildEntity.enabled(isCompositeEntity);
    }
    else if (isCallerAllCompleted)
    {
        isCompositeEntity = (DMFEntity::find(DMFDefinitionGroupExecution.Entity).EntityType == DMFEntityTypes::CompositEntity);

        ViewStagingButtonHeaderEntity.enabled(!isCompositeEntity);
        ViewStagingButtonChildEntity.enabled(isCompositeEntity);
    }
}

/// <summary>
/// Display execution status
/// </summary>
/// <param name = "_dmfDefinitionEntity">DMFDefinitionGroupEntity buffer</param>
/// <returns>Image container</returns>
public display container executionStatus(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    DMFExecutionSummaryStatus summaryStatus = _dmfDefinitionGroupExecution.GetExecutionSummaryStatus();
    return DMFExecutionStatusHelper::GetExecutionSummaryStatusImageReference(summaryStatus);
}

/// <summary>
/// Get the count of pending records for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity.</param>
/// <returns>The count of records still pending.</returns>
public display str getPending(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    if (_dmfDefinitionGroupExec)
    {
        return int642Str(DMFExecutionStatusHelper::getPending(_dmfDefinitionGroupExec));
    }

    return '';
}

/// <summary>
/// Get the count of target records for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity.</param>
/// <returns>The count of records in target.</returns>
public display str getTarget(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    if (_dmfDefinitionGroupExec)
    {
        if (element.parmExecutionOperation() != DMFOperationType::Export)
        {
            return int642Str(_dmfDefinitionGroupExec.NumOfTargetNew + _dmfDefinitionGroupExec.NumOfTargetUpdated);
        }
    }

    return '';
}

/// <summary>
/// Get the status of target record for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity</param>
/// <returns>The status of record in target.</returns>
public display str getStatus(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    DMFExecutionSummaryStatus summaryStatus = _dmfDefinitionGroupExec.GetExecutionSummaryStatus();
    return enum2Str(summaryStatus);
}

/// <summary>
/// Datasource active method
/// </summary>
/// <returns>Integer</returns>
public int active()
{
    int ret;

    ret = super();

    element.allowButtonEditable();

    return ret;
}

/// <summary>
/// Get the execution errror details of target record for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity</param>
/// <returns>The execution errror details of record in target.</returns>
internal display str getExecutionDetails(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    str executionErrorDetails = "";

    if(_dmfDefinitionGroupExec.GetExecutionSummaryStatus() != DMFExecutionSummaryStatus::Succeeded)
    {
        DMFStagingLog stagingLog;
        DMFStagingLogDetails stagingLogDetails;

        while select Text from stagingLogDetails
        order by stagingLogDetails.RecId desc
        join stagingLog
        where stagingLog.RecId == stagingLogDetails.StagingLog
            && stagingLog.ExecutionId == _dmfDefinitionGroupExec.ExecutionId
            && stagingLog.EntityName == _dmfDefinitionGroupExec.Entity
            && stagingLogDetails.MessageSeverity == MessageSeverity::Error
        {
            executionErrorDetails += stagingLogDetails.Text + "\n";
        }
    }

    return executionErrorDetails;
}

/// <summary>
/// Selection change method of datasource
/// </summary>
public void selectionChanged()
{
    super();

    childEntityExecution_DS.executeQuery();
}

/// <summary>
/// Get the staging log of target record for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity</param>
/// <returns>The staging log of record.</returns>
internal display SysInfoLogStr staginglogText(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    SysInfoLogStr   logText = '';
    DMFStagingLog   stagingLog;

    select stagingLog 
        where stagingLog.EntityName == _dmfDefinitionGroupExec.Entity
           && stagingLog.ExecutionId == _dmfDefinitionGroupExec.ExecutionId;

    logText = stagingLog.logText();

    return logText;
}

/// <summary>
/// Get the target log details of target record for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity</param>
/// <returns>The target log of record in target.</returns>
internal display SysInfoLogStr targetLogText(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    #define.NewLine('\n')
    ;
    DMFStagingValidationLog stagingValidationLog;
    str                     logStr;
    SysInfoLogStr           logText;

    while select ErrorMessage, RecId from stagingValidationLog
        order by stagingValidationLog.RecId desc
        where stagingValidationLog.DefinitionGroupName == _dmfDefinitionGroupExec.DefinitionGroup
           && stagingValidationLog.ExecutionId == _dmfDefinitionGroupExec.ExecutionId
           && stagingValidationLog.EntityName   == _dmfDefinitionGroupExec.Entity
    {

        logStr = #NewLine + stagingValidationLog.ErrorMessage;

        logText += logStr;
    }

    return logText;
}

/// <summary>
/// Get the error log details of staging or target record for an entity in execution.
/// </summary>
/// <param name = "_dmfDefinitionGroupExec">The execution entity</param>
/// <returns>The error log details of staging or target record.</returns>
internal display SysInfoLogStr logText(DMFDefinitionGroupExecution _dmfDefinitionGroupExec)
{
    SysInfoLogStr  logText;

    if (_dmfDefinitionGroupExec.StagingStatus == DMFBatchJobStatus::Error)
    {
        logText = this.staginglogText(_dmfDefinitionGroupExec);
    }
    else if (_dmfDefinitionGroupExec.TargetStatus == DMFBatchJobStatus::Error)
    {
        logText = this.targetlogText(_dmfDefinitionGroupExec);
    }

    return logText;
}

/// <summary>
/// Datasource execute query
/// </summary>
public void executeQuery()
{

    this.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroupExecution, ExecutionId));
    this.queryBuildDataSource().addRange(fieldNum(DMFDefinitionGroupExecution, ExecutionId)).value(queryValue(dmfDefinitionGroupExecution.ExecutionId));

    super();
}

